const canvas=$('#map'),ctx=canvas.getContext('2d');let W=800,H=700,dpr=1,view={x:20,y:52,z:1};
const project=(lon,lat)=>[lon,-Math.log(Math.tan(Math.PI/4+lat*Math.PI/360))*180/Math.PI];
const inverse=(x,y)=>[x,(2*Math.atan(Math.exp(-y*Math.PI/180))-Math.PI/2)*180/Math.PI];
function units(){return Math.min(W/70,H/51)*view.z}function screen(lon,lat){let p=project(lon,lat),c=project(view.x,view.y),u=units();return[(p[0]-c[0])*u+W/2,(p[1]-c[1])*u+H/2]}
function geo(x,y){let c=project(view.x,view.y),u=units();return inverse((x-W/2)/u+c[0],(y-H/2)/u+c[1])}
function rings(f){return f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates}
function insideRing(p,r){let yes=false;for(let i=0,j=r.length-1;i<r.length;j=i++){let a=r[i],b=r[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])yes=!yes}return yes}
