function start(){ptDraft=null;ptStroke=null;clearInterval(timer);timer=null;mode=$('.mode.active').dataset.mode;let player=$('#country').value;state={v:1,player,mode,startMonth:mode==='control'?9:0,turn:0,approval:58,legitimacy:75,term:1,election:48,ended:false,logs:[],wars:[],occupations:[],countries:{},event:null};for(const f of features){let c=f.properties.code,p=profile[c]||[15,1,8];state.countries[c]={code:c,gdp:p[0],pop:p[1],force:p[2],ready:72,treasury:p[0]*.035,debt:p[0]*.5,tax:32,health:7,education:5,defense:3,infra:5,growth:2,relations:{},allies:mode==='free'?[]:NATO.includes(c)?NATO.filter(x=>x!==c&&world[x]):c==='RU'?['BY']:c==='BY'?['RU']:[],trades:[],sanctions:[],mobilized:false,owner:c}}
 target=player==='LV'?'LT':player==='RU'?'UA':'LV';if(mode==='control')state.occupations.push({a:'RU',b:'UA',scenario:true,geometry:occupationData.geometry,snapshot:occupationData.properties.snapshot_date});simEnsureWorld();log(`You have taken office in ${name(player)}. The electorate expects stability and progress.`);if(mode==='control')log('Occupation snapshot: 27 October 2026 (DeepState). Russia and Ukraine begin at war. Territorial control now changes along the contact line each month. Sovereignty remains Ukrainian.',true);view={x:20,y:52,z:1};$('#setup').close();render();draw()}

function render(){if(!state)return;$('#map').style.cursor=ptDraft&&ptDraft.brush!=='pan'?'crosshair':'grab';let n=nation(),e=economy(n);$('#nationTitle').textContent=name(state.player);$('#nationMeta').textContent=`${mode==='free'?'Non-aligned start':NATO.includes(state.player)?'NATO · collective security':'Independent foreign policy'} / Term ${state.term}`;$('#date').textContent=dates();$('#modeLabel').textContent=mode==='legal'?'RECOGNIZED BORDERS':mode==='control'?'2026 CONTROL SCENARIO':'A WORLD UNBOUND';$('#stats').innerHTML=[['PUBLIC APPROVAL',Math.round(state.approval)+'%'],['TREASURY',money(n.treasury)],['ECONOMIC GROWTH',n.growth.toFixed(1)+'%'],['MONTHLY BALANCE',(e.net+ptCashflow(n.code)>=0?'+':'−')+money(Math.abs(e.net+ptCashflow(n.code)))]].map(([l,v])=>`<div class="stat"><label>${l}</label><strong>${v}</strong></div>`).join('');$('#play').textContent=timer?'Ⅱ':'▶';$('#advance').disabled=state.ended||!!ptDraft;$('#play').disabled=state.ended||!!ptDraft;renderPanel();renderTarget();$('#feed').innerHTML=state.logs.slice(0,9).map(l=>`<div class="dispatch ${l.war?'war':''}"><time>${l.date.toUpperCase()}</time>${l.t}</div>`).join('');draw()}
