function renderPanel(){let n=nation(),e=economy(n),html='';if(tab==='cabinet'){html=`<div class="card"><div class="row"><span>Next election</span><b>${Math.max(0,state.election-state.turn)} months</b></div><div class="bar"><i style="width:${state.approval}%"></i></div><p>Approval ${Math.round(state.approval)}% · Legitimacy ${Math.round(state.legitimacy)}%</p></div><h3>Domestic agenda</h3>${actionButton('campaign','Public outreach · '+money(n.gdp*.001))}${actionButton('reform','Anti-corruption reform · '+money(n.gdp*.002))}${actionButton('stimulus','Economic stimulus · '+money(n.gdp*.006))}${actionButton('snap','Call a snap election')}<p class="note">Elections every four years. High taxes, debt, casualties, and poor services cost votes. Elections can end your administration.</p>`;if(state.event)html+=`<div class="card"><b>${state.event.title}</b><p>${state.event.text}</p>${actionButton('eventFund','Fund a response · '+money(n.gdp*.003))}${actionButton('eventWait','Let markets adjust')}</div>`;
 }else if(tab==='budget'){html=`<p class="note">Annual allocations as % of GDP. Changes take effect next month.</p>`;for(let [key,label,min,max] of [['tax','Effective tax revenue',15,55],['health','Healthcare',1,15],['education','Education',1,12],['defense','Defence',1,20],['infra','Infrastructure',1,12]])html+=`<label class="row">${label}<b id="val-${key}">${n[key]}%</b></label><input aria-label="${label}" type="range" min="${min}" max="${max}" value="${n[key]}" data-budget="${key}">`;html+=`<div class="card"><div class="row"><small>Monthly revenue</small><b>${money(e.revenue)}</b></div><div class="row"><small>Monthly expenditure</small><b>${money(e.spend)}</b></div><div class="row"><small>Public debt / GDP</small><b>${(n.debt/n.gdp*100).toFixed(0)}%</b></div><div class="row"><small>Treaty cashflow / month</small><b>${money(ptCashflow(n.code))}</b></div><p>Reparations use available reserves; unpaid amounts remain owed. Includes 7% administration; interest is charged monthly. Deficits use reserves, then borrowing.</p></div>`;
 }else{html=`<div class="card"><div class="row"><span>Military power</span><b>${n.force.toFixed(0)}</b></div><div class="row"><span>Readiness</span><b>${n.ready.toFixed(0)}%</b></div><div class="row"><span>Morale</span><b>${Math.round(n.morale)}%</b></div><div class="row"><span>Defence / GDP</span><b>${n.defense}%</b></div></div>${actionButton('train','Run military exercises · '+money(n.gdp*.002))}${actionButton('recruit','Recruit & procure · '+money(n.gdp*.008))}${actionButton('mobilize',n.mobilized?'Demobilize reserves':'Mobilize reserves')}<h3>Active campaigns</h3>`;let wars=state.wars.filter(w=>([w.a,w.b].includes(state.player)&&w.active)||w.scenario);html+=wars.length?wars.map(w=>wcCard(w)).join(''):'<p class="note">No active fronts. Select another country for diplomatic and military options.</p>';html+='<p class="note">Force values are game indices. Offensive posture advances faster but increases losses. Allied support helps defence. Overseas invasions have a supply penalty.</p>'}if(tab==='cabinet')html+=simOffersHTML();if(tab==='forces')html+=simFrontCard();$('#panel').innerHTML=html}
function renderTarget(){if(!state)return;if(ptDraft){ptPanel();return;}let c=target,n=selected(),ours=state.player===c,w=wcFind(state.player,c);$('#target').innerHTML=`<select aria-label="Inspect a country" id="targetSelect">${features.slice().sort((a,b)=>a.properties.name.localeCompare(b.properties.name)).map(f=>`<option value="${f.properties.code}" ${c===f.properties.code?'selected':''}>${f.properties.name}</option>`).join('')}</select><h2 class="targetTitle">${name(c)}</h2><span class="tag">${n.owner!==c?'Administered by '+name(n.owner):allied(c,state.player)?'Allied':mode!=='free'&&NATO.includes(c)?'NATO':EU.includes(c)&&mode!=='free'?'European Union':'Non-aligned'}</span><span class="tag">${ours?'Home country':relation(c)+' relations'}</span><div class="row"><small>Economy</small><b>${money(n.gdp)}</b></div><div class="row"><small>Military power</small><b>${n.force.toFixed(0)}</b></div><div class="row"><small>Population</small><b>${n.pop}m</b></div>${ours?'<p class="note">Your administration. Use the cabinet to set domestic policy.</p>':`${actionButton('improve','Diplomatic visit · '+money(nation().gdp*.0005))}${actionButton('trade',nation().trades.includes(c)?'End trade agreement':'Propose trade agreement')}${actionButton('alliance',allied(c,state.player)?'Leave bilateral / alliance ties':'Propose defence pact')}${actionButton('aid','Send foreign aid · '+money(nation().gdp*.002))}${actionButton('sanction',nation().sanctions.includes(c)?'Lift sanctions':'Impose sanctions')}${ptDiplomacyButton(c)}`}<p class="note">${w?'Active war. Ceasefire acceptance depends on campaign progress and relative strength.':ours?'':allied(c,state.player)?'A declaration of war will sever your alliance ties and damage legitimacy.':'Defence pacts add coalition support when a member is attacked.'}</p>${ptStatus(c)}${simInspector(c)}`}
function pay(amount){let n=nation();if(n.treasury<amount){notify('Insufficient reserves. Adjust the budget or build a surplus.');return false}n.treasury-=amount;return true}
function act(a){if(!state||state.ended)return;if(a==='treaty'){ptOpen();return;}if(a.startsWith('acceptOffer_')){simAcceptOffer(a.slice(12));render();return;}if(a.startsWith('dismissOffer_')){state.offers=state.offers.filter(o=>o.from!==a.slice(13));render();return;}let n=nation(),t=selected(),cost=0;if(['campaign','reform','stimulus','train','recruit','improve','aid','eventFund'].includes(a)){cost=n.gdp*({campaign:.001,reform:.002,stimulus:.006,train:.002,recruit:.008,improve:.0005,aid:.002,eventFund:.003}[a]);if(!pay(cost))return}
 switch(a){case 'campaign':state.approval=clamp(state.approval+3,0,100);log('Public outreach improves support for the administration.');break;case 'reform':state.legitimacy=clamp(state.legitimacy+7,0,100);state.approval=clamp(state.approval+2,0,100);log('Transparency reforms strengthen public confidence.');break;case 'stimulus':n.gdp*=1.006;state.approval=clamp(state.approval+2,0,100);log('A targeted investment package expands the economy.');break;case 'snap':election();break;case 'train':n.ready=clamp(n.ready+9,0,100);log('Military exercises improve readiness.');break;case 'recruit':n.force+=Math.max(2,n.gdp*.012);log('New equipment and personnel join the armed forces.');break;case 'mobilize':n.mobilized=!n.mobilized;state.approval=clamp(state.approval+(n.mobilized?-6:3),0,100);log(n.mobilized?'Reserves mobilized. Military power rises; upkeep and public pressure increase.':'Reserves stand down.');break;case 'improve':n.relations[target]=clamp(relation(target)+12,-100,100);log(`Diplomatic talks with ${name(target)} improve relations.`);break;case 'aid':t.treasury+=cost;if(target==='UA'&&state.front?.active)state.front.support=clamp(state.front.support+cost*.04,0,2);n.relations[target]=clamp(relation(target)+16,-100,100);state.legitimacy=clamp(state.legitimacy+2,0,100);log(`An aid package is delivered to ${name(target)}.`);break;case 'trade':if(n.trades.includes(target)){n.trades=n.trades.filter(c=>c!==target);t.trades=t.trades.filter(c=>c!==state.player);log(`Trade agreement with ${name(target)} ended.`)}else if(relation(target)>=35&&!simAtWar(state.player,target)){n.trades.push(target);t.trades.push(state.player);log(`A trade agreement with ${name(target)} is signed.`)}else notify('Trade proposal rejected. Reach 35 relations and end hostilities.');break;case 'alliance':if(allied(state.player,target)){n.allies=n.allies.filter(c=>c!==target);t.allies=t.allies.filter(c=>c!==state.player);n.relations[target]=relation(target)-20;log(`Defence ties with ${name(target)} severed.`)}else if(relation(target)>=60&&!simAtWar(state.player)&&!simAtWar(target)){n.allies.push(target);t.allies.push(state.player);log(`A mutual defence pact with ${name(target)} is signed.`)}else notify('Defence pact rejected. Reach 60 relations and resolve active wars.');break;case 'sanction':if(n.sanctions.includes(target))n.sanctions=n.sanctions.filter(c=>c!==target);else{n.sanctions.push(target);n.relations[target]=clamp(relation(target)-25,-100,100)}log(`Sanctions on ${name(target)} ${n.sanctions.includes(target)?'imposed':'lifted'}.`);break;case 'war':declareWar();break;case 'peace':peace();break;case 'eventFund':state.approval=clamp(state.approval+4,0,100);log('Emergency funding stabilizes the situation.');state.event=null;break;case 'eventWait':state.approval=clamp(state.approval-3,0,100);log('The cabinet declines emergency intervention.');state.event=null;break}render()}
function makeWar(a,b){return wcCreateWar(a,b);}
function declareWar(){
 if(target===state.player)return;if(simAtWar(state.player,target)){notify('You are already at war with this country.');return;}if(!ptBeforeWar(state.player,target))return;if(simResumeFront())return;
 if(selected().owner!==target){notify('That country is already administered by another state.');return;}
 let n=nation(),allies=n.allies.filter(c=>c===target||allied(c,target));for(let c of allies)state.countries[c].allies=state.countries[c].allies.filter(x=>x!==state.player);n.allies=n.allies.filter(c=>!allies.includes(c));
 n.relations[target]=-100;state.legitimacy=clamp(state.legitimacy-18,0,100);state.approval=clamp(state.approval-8,0,100);
 let war=wcCreateWar(state.player,target);state.wars.push(war);log(`War declared on ${name(target)}. One shared front opens. ${name(state.player)} has +25% opening initiative for three months.`,true);
 tab='forces';$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));notify('War declared. Advance time to move the shared front.');
}
function peace(){let w=wcFind(state.player,target);if(w)wcPeace(w);}
function election(){let score=state.approval*.8+state.legitimacy*.2;let win=score>=50;log(`Election: your coalition receives ${score.toFixed(1)}% of the modeled vote. ${win?'A renewed mandate.':'The opposition forms a government.'}`);if(win){state.term++;state.election=state.turn+48;state.approval=clamp(state.approval+3,0,100);info('Mandate renewed',`<p>Your coalition won <b>${score.toFixed(1)}%</b>. You begin term ${state.term}. The next regular election is in four years.</p>`)}else{state.ended=true;clearInterval(timer);timer=null;info('A peaceful transfer of power',`<p>Your coalition won ${score.toFixed(1)}%. Your administration ends after ${state.turn} months.</p><p>Start a new campaign from the top bar to try a different policy.</p>`)}}
function advance(){if(!state||state.ended||ptDraft)return;simEnsureWorld();state.turn++;simRunAI();for(let c in state.countries){let n=state.countries[c],e=economy(n);n.growth=clamp(1-Math.min(3,ptSanctions(c)*.22)+(n.education-5)*.14+(n.infra-5)*.2+(n.health-6)*.07-(n.tax-30)*.07+n.trades.length*.22-n.sanctions.length*.18-(n.mobilized?.8:0)-(simAtWar(c)?2:0)-Math.max(0,n.debt/n.gdp-.8)*2,-8,9);n.gdp*=1+n.growth/1200;n.treasury+=e.net;if(n.treasury<0){n.debt-=n.treasury;n.treasury=0}n.force+=n.gdp*n.defense/100*.025;n.ready=clamp(n.ready+.7+(n.defense-3)*.18,25,100);if(n.owner!==c)n.treasury*=.95}
let n=nation(),war=simAtWar(state.player);state.approval=clamp(state.approval+(.14+(n.health-6)*.09+(n.education-5)*.06+n.growth*.07-(n.tax-31)*.08-(war?.6:0)-(n.mobilized?.3:0)-Math.max(0,n.debt/n.gdp-.8)*.8),0,100);
ptMonthly();wcAdvanceAll();
if(state.turn%5===0&&!state.event){state.event=[{title:'Energy prices rise',text:'Households face higher energy bills. The cabinet can offer temporary relief.'},{title:'Regional infrastructure dispute',text:'Local governments request funding to repair critical transport links.'},{title:'Hospitals under pressure',text:'A capacity shortage brings healthcare funding into the headlines.'}][Math.floor(Math.random()*3)];log(state.event.title+'. The cabinet must choose a response.');state.approval=clamp(state.approval-1,0,100)}if(state.turn%3===0){for(let c in state.countries){if(c===state.player)continue;let t=state.countries[c];t.force*=1.003;let r=relation(c);if(n.sanctions.includes(c))t.gdp*=.999;if(r<0&&Math.random()<.1)n.relations[c]=clamp(r+2,-100,100)}log(`Treasury bulletin: ${n.growth.toFixed(1)}% annual growth; ${Math.round(state.approval)}% public approval.`)}if(!state.ended&&state.turn>=state.election)election();render();save(false)}
function save(show=true){if(!state)return;try{localStorage.setItem('mandate-europe-v1',JSON.stringify({state,view}));if(show)notify('Campaign saved on this device.')}catch(e){if(show)notify('Browser storage is full or unavailable.')}}
function migrateOccupation(saved){
 // Preserve saved campaigns while replacing only the old, hardcoded starting overlay.
 if(saved.mode==='control'&&occupationData){for(let occ of saved.occupations){if(occ.a==='RU'&&occ.b==='UA'&&(occ.scenario||(!occ.geometry&&occ.step===undefined))){delete occ.cells;occ.scenario=true;occ.geometry=occupationData.geometry;occ.snapshot=occupationData.properties.snapshot_date}}}
}
function resume(){ptDraft=null;ptStroke=null;try{let v=JSON.parse(localStorage.getItem('mandate-europe-v1'));if(v?.state?.v!==1)throw Error();if(v.state.warfare!==3&&v.state.wars?.some(w=>!w.shared)){try{if(!localStorage.getItem('mandate-before-shared-front'))localStorage.setItem('mandate-before-shared-front',JSON.stringify(v));}catch{}}state=v.state;ptEnsure();mode=state.mode;migrateOccupation(state);simEnsureWorld();view=v.view;target=state.player;$('#setup').close();render();save(false)}catch{notify('This save could not be loaded.')}}
function color(c){if(!state)return '#425a56';let n=state.countries[c],owner=n.owner;if(owner===state.player)return '#a5bd79';if(owner!==c)return color(owner);let layer=$('#layer').value;if(layer==='relations'){let r=relation(c);return r>40?'#629d84':r<0?'#9d625a':'#657c7a'}if(layer==='alliance')return NATO.includes(c)&&mode!=='free'?'#4e7784':(c==='RU'||c==='BY')&&mode!=='free'?'#976d63':EU.includes(c)&&mode!=='free'?'#6c8681':'#5d655e';let palette=['#4f6e67','#5f776a','#70816b','#536c72','#77846f','#617e77','#7b7864','#567873'];return palette[(c.charCodeAt(0)*3+c.charCodeAt(1))%palette.length]}
function draw(){if(!features.length)return;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#0e202a';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#25404b';ctx.lineWidth=.45;for(let lon=-30;lon<=70;lon+=10){let a=screen(lon,30),b=screen(lon,74);ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke()}for(let lat=30;lat<=75;lat+=5){let a=screen(-35,lat),b=screen(75,lat);ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke()}
for(let f of features){let c=f.properties.code;path(f);ctx.fillStyle=wcTerritoryColor(c,wcRoot(c));ctx.fill('evenodd');ctx.strokeStyle='#172c31';ctx.lineWidth=.8;ctx.stroke()}
if(state){for(let occ of state.occupations){if(occ.scenario)continue;path(world[occ.b].feature);ctx.save();ctx.clip('evenodd');ctx.fillStyle=wcTerritoryColor(occ.b,wcRoot(occ.a));if(occ.geometry){path(occ);ctx.fill('evenodd');}else drawCells(occ.cells,occ.step||.16);ctx.restore()}simDrawFront();wcDraw();ptDrawTitles();ptDraw();for(let c of [state.player,target,hovered]){if(!c||!world[c])continue;path(world[c].feature);ctx.strokeStyle=c===state.player?'#d8eba6':c===target?'#f0d7a5':'#e6ede8';ctx.lineWidth=c===target?2:1.4;ctx.stroke()}}
let z=view.z;if(z<4.5){ctx.textAlign='center';for(let c in world){let p=screen(...world[c].center);if(p[0]<-30||p[0]>W+30||p[1]<0||p[1]>H)continue;let small=['LU','AD','MC','LI','SM','VA','MT','XK','ME'].includes(c);if(small&&z<2.5)continue;if(z<1.4)continue;ctx.font=(c===state?.player?'600 ':'500 ')+(z<1.4?9:11)+'px system-ui';ctx.fillStyle=c===state?.player?'#172c27':'#e0e9df';ctx.shadowColor='#203b35';ctx.shadowBlur=2;ctx.fillText(z>1.4?name(c):c,p[0],p[1]);ctx.shadowBlur=0}}
if(z>.95){ctx.textAlign='left';let occupied=[],drawn=0;for(let p of places){if(drawn>900)break;let threshold=z<1.8?900000:z<3?300000:z<5?70000:z<9?15000:z<18?3000:z<32?500:0;if(!p[5]&&p[3]<threshold)continue;let s=screen(p[1],p[2]);if(s[0]<10||s[0]>W-50||s[1]<65||s[1]>H-30)continue;let textWidth=Math.min(130,p[0].length*6);if(occupied.some(q=>Math.abs(q[1]-s[1])<15&&s[0]<q[0]+q[2]&&s[0]+textWidth>q[0]))continue;occupied.push([s[0],s[1],textWidth]);drawn++;ctx.beginPath();ctx.arc(...s,p[5]?2.7:1.6,0,Math.PI*2);ctx.fillStyle=p[5]?'#e6e9c9':'#c4d2bd';ctx.fill();ctx.font=(p[5]?'600 ':'')+(p[5]?11:10)+'px system-ui';ctx.strokeStyle='#193136';ctx.lineWidth=3;ctx.strokeText(p[0],s[0]+6,s[1]+3);ctx.fillStyle='#e3ebdc';ctx.fillText(p[0],s[0]+6,s[1]+3)}}
ctx.save();ctx.font='italic 13px Georgia';ctx.fillStyle='#74909c';ctx.textAlign='center';if(view.z<3)for(let [label,x,y] of [['ATLANTIC OCEAN',-17,49],['BALTIC SEA',19,58],['BLACK SEA',34,43],['MEDITERRANEAN SEA',14,35.5],['NORTH SEA',3,57]]){let p=screen(x,y);ctx.fillText(label,...p)}ctx.restore();$('#scale').textContent=view.z.toFixed(1)+'× · '+(view.z>18?'SETTLEMENTS':view.z>4?'CITIES & TOWNS':'EUROPE')}
function drawCells(cells,step){for(let p of cells){let a=screen(p[0],p[1]+step),b=screen(p[0]+step,p[1]);if(b[0]<0||a[0]>W||b[1]<0||a[1]>H)continue;ctx.fillRect(a[0],a[1],b[0]-a[0]+.5,b[1]-a[1]+.5)}}
function resize(){let r=canvas.getBoundingClientRect();W=r.width;H=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=W*dpr;canvas.height=H*dpr;draw()}
function zoom(f,x=W/2,y=H/2){let before=geo(x,y);view.z=clamp(view.z*f,.6,80);let after=geo(x,y);view.x+=before[0]-after[0];view.y=clamp(view.y+before[1]-after[1],30,73);draw()}
let pointers=new Map(),drag=null,pinch=null;
canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,[e.offsetX,e.offsetY]);drag={x:e.offsetX,y:e.offsetY,cx:view.x,cy:view.y,moved:false};if(pointers.size===2){let p=[...pointers.values()];pinch=Math.hypot(p[0][0]-p[1][0],p[0][1]-p[1][1])}});
canvas.addEventListener('pointermove',e=>{if(pointers.has(e.pointerId)){pointers.set(e.pointerId,[e.offsetX,e.offsetY]);if(pointers.size===2){let p=[...pointers.values()],d=Math.hypot(p[0][0]-p[1][0],p[0][1]-p[1][1]);if(pinch)zoom(d/pinch,(p[0][0]+p[1][0])/2,(p[0][1]+p[1][1])/2);pinch=d;drag.moved=true;return}let dx=e.offsetX-drag.x,dy=e.offsetY-drag.y;if(Math.abs(dx)+Math.abs(dy)>4)drag.moved=true;let c=project(drag.cx,drag.cy);[view.x,view.y]=inverse(c[0]-dx/units(),c[1]-dy/units());view.y=clamp(view.y,30,73);draw()}else{let c=getAt(geo(e.offsetX,e.offsetY));if(c!==hovered){hovered=c;draw()}$('#hover').style.display=c?'block':'none';if(c){let controller=state?.warfare===3?wcOwner(wcKey(...geo(e.offsetX,e.offsetY))):c;$('#hover').textContent=controller&&controller!==c?name(c)+' · '+name(controller)+' control':name(c);$('#hover').style.left=clamp(e.offsetX+15,0,W-130)+'px';$('#hover').style.top=e.offsetY+15+'px'}}});
canvas.addEventListener('pointerup',e=>{let moved=drag?.moved;pointers.delete(e.pointerId);if(!pointers.size){if(!moved&&state&&!ptDraft){let c=getAt(geo(e.offsetX,e.offsetY));if(c){target=c;renderTarget();draw()}}drag=null;pinch=null}});canvas.addEventListener('pointercancel',()=>{pointers.clear();drag=null;pinch=null});canvas.addEventListener('pointerleave',()=>{$('#hover').style.display='none'});canvas.addEventListener('wheel',e=>{e.preventDefault();zoom(Math.exp(-e.deltaY*.0015),e.offsetX,e.offsetY)},{passive:false});
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(b)act(b.dataset.action);let t=e.target.closest('[data-tab]');if(t){tab=t.dataset.tab;$$('[data-tab]').forEach(b=>b.classList.toggle('active',b===t));if(state)renderPanel()}let m=e.target.closest('[data-mode]');if(m){$$('.mode').forEach(b=>b.classList.toggle('active',b===m));mode=m.dataset.mode;setupPreview()}});
document.addEventListener('input',e=>{if(e.target.dataset.budget){let k=e.target.dataset.budget;nation()[k]=Number(e.target.value);$('#val-'+k).textContent=e.target.value+'%'} });document.addEventListener('change',e=>{if(e.target.dataset.budget)render();if(e.target.id==='targetSelect'){target=e.target.value;renderTarget();draw()}if(e.target.id==='frontPosture'&&state.front){state.front.postures[state.player]=e.target.value;renderPanel();}if(e.target.dataset.stance){state.wars.find(w=>w.id===e.target.dataset.stance).stance=e.target.value;renderPanel()}});
$('#start').onclick=start;$('#country').onchange=setupPreview;$('#resume').onclick=resume;$('#closeInfo').onclick=()=>$('#info').close();$('#save').onclick=()=>save();$('#advance').onclick=advance;$('#play').onclick=()=>{if(!state||state.ended||ptDraft)return;if(timer){clearInterval(timer);timer=null}else timer=setInterval(advance,1800);render()};$('#new').onclick=()=>{clearInterval(timer);timer=null;$('#setup').showModal();$('#resume').hidden=!localStorage.getItem('mandate-europe-v1')};$('#zin').onclick=()=>zoom(1.5);$('#zout').onclick=()=>zoom(1/1.5);$('#home').onclick=()=>{view={x:20,y:52,z:1};draw()};$('#layer').onchange=draw;$('#brand').onclick=e=>{e.preventDefault();$('#help').click()};
$('#help').onclick=()=>info('The art of governing','<p><b>1. Choose a country and scenario.</b> You begin with an electoral mandate in January 2026 (October for the dated occupation scenario). Every turn advances one month.</p><p><b>2. Balance your budget.</b> Fund services and defence while managing taxes, reserves and debt. Build approval before the election every 48 months.</p><p><b>3. Make diplomatic choices.</b> Select a country on the map or in Foreign Affairs. Improve relations to unlock trade (35) and defence pacts (60).</p><p><b>4. Manage campaigns.</b> A declaration opens one shared line of control. Small adjacent hex sectors have one controller. The aggressor receives +25% initiative for the first three monthly turns; then strength, morale, readiness, war fatigue, politics and supply determine movement. Counterattacks recover home territory first. Capturing or liberating a major city boosts morale and lowers enemy morale; capitals matter more, with a six-month cooldown against capture farming.</p><p><b>AI governments.</b> Other countries make budget, investment, readiness, aid and diplomatic decisions. Each has an illustrative strategic profile and modeled elections; inspect its latest decision in Foreign Affairs. Incoming proposals appear in Cabinet.</p><p><b>Ukraine front.</b> The control scenario begins at war. The shared line moves in the stronger side of the turn, including when you play a third country. Counterattacks can recapture lost territory. The long-running 2026 war does not receive a fresh opening bonus. In Forces, Russia and Ukraine can choose their front posture.</p><p><b>5. Explore.</b> Drag to pan, scroll or pinch to zoom. Over 100,000 real settlements become visible by scale. Saves stay in this browser. This is a simplified sandbox with illustrative statistics.</p>');
$('#sources').onclick=()=>info('Map & scenario notes','<p>Country geometry: <a href="https://github.com/datasets/geo-countries" target="_blank" rel="noopener">geo-countries / Natural Earth</a> (public domain), simplified for performance. Settlement names and coordinates: <a href="https://www.geonames.org/" target="_blank" rel="noopener">GeoNames</a>, cities500 dataset, CC BY 4.0. The atlas includes small settlements with roughly 500+ inhabitants; it is not every village.</p><p>Recognized-border modes place Crimea in Ukraine. Kosovo is shown separately with disputed recognition. Other territorial disputes are simplified; this is not an authoritative legal atlas.</p><p>The 2026 control scenario uses a <b>27 October 2026 DeepStateMap occupation snapshot</b> via <a href="https://github.com/cyterat/deepstate-map-data" target="_blank" rel="noopener">cyterat/deepstate-map-data</a>, distributed under <a href="CONTROL-LICENSE.txt" target="_blank" rel="noopener">GPL-3.0</a>. Geometry is clipped to Ukraine and lightly simplified. It is a dated reported-control estimate, not a live or surveyed frontline. Sovereignty remains Ukrainian. The mode starts in October 2026 with an <b>active Russia–Ukraine war</b>. The dated outline is sampled onto the combat hex grid; small adjacent sectors can change control each month. A single shared front advances or retreats based on strength, morale, readiness, posture, local conditions and aid. Its fine hex sectors are roughly a few kilometres across. Starting occupation and later advances are rendered on the same fine hex grid, using darker shades of the controlling country. These are fictional simulated outcomes, not predictions or live updates. Previous scenario saves migrate to the active front; saved front progress and ceasefires persist.</p><p>Modern alliance modes initialize European NATO members and Russia–Belarus defence ties. The EU is an economic affiliation, not an automatic war bloc. NATO defence is represented by coalition strength; America and Canada provide no separately simulated armies. Non-NATO pacts, treaty procedures and national election systems are simplified.</p><p>Peace treaties become available after a ceasefire. Paint demands or concessions, set reparations and vassalization, and negotiate a 1–50-year truce. Accepted cessions transfer in-game sovereignty. Breaking a truce damages legitimacy and relations and risks international sanctions.</p><p>Game source: <a href="https://github.com/jg-tech-aosp/mandate" target="_blank" rel="noopener">jg-tech-aosp/mandate</a>.</p><p>Major cities affect military morale and public support when control changes. New wars have a three-turn initiative phase. Legacy mirrored invasions restart at the shared border; their economy and political progress are retained. Existing Ukraine-front gains are translated to the finer grid.</p><p>Sources: <a href="https://www.nato.int/en/about-us/organization/nato-member-countries" target="_blank" rel="noopener">NATO membership</a>; <a href="https://ukraine.ohchr.org/en" target="_blank" rel="noopener">UN human rights mission in Ukraine</a>. All economic and military values are illustrative, not factual 2026 statistics.</p>');
window.addEventListener('resize',resize);new ResizeObserver(resize).observe(canvas);$('#setup').showModal();$('#start').disabled=true;
Promise.all([fetch('borders-grid.json').then(r=>{if(!r.ok)throw Error('Grid borders unavailable');return r.json()}),fetch('countries.json').then(r=>{if(!r.ok)throw Error('Atlas unavailable');return r.json()}),fetch('places.json').then(r=>{if(!r.ok)throw Error('Settlements unavailable');return r.json()}).then(async p=>Array.isArray(p)?p:(await Promise.all(p.parts.map(async url=>{let r=await fetch(url);if(!r.ok)throw Error('Settlement part unavailable');return r.json()}))).flat()),fetch('occupation.json').then(r=>{if(!r.ok)throw Error('Occupation snapshot unavailable');return r.json()})]).then(([borders,data,p,occ])=>{wcLoadBorders(borders);features=data.features;places=p;occupationData=occ;for(let f of features){let c=f.properties.code,capital=places.find(p=>p[4]===c&&p[5]),r=rings(f).flatMap(p=>p[0]);world[c]={name:f.properties.name,feature:f,center:capital?[capital[1],capital[2]]:[r.reduce((s,p)=>s+p[0],0)/r.length,r.reduce((s,p)=>s+p[1],0)/r.length]}}$('#country').innerHTML=features.slice().sort((a,b)=>a.properties.name.localeCompare(b.properties.name)).map(f=>`<option value="${f.properties.code}" ${f.properties.code==='LV'?'selected':''}>${f.properties.name}</option>`).join('');$('#loadStatus').textContent=`${features.length} countries · ${places.length.toLocaleString()} settlements · Ready`;$('#start').disabled=false;$('#resume').hidden=!localStorage.getItem('mandate-europe-v1');setupPreview();resize()}).catch(e=>{$('#loadStatus').textContent='Could not load atlas. Reload the page to retry.';console.error(e)});
